{
  "summary": "Clamped discountPercent to a max of 100 and used ?? 0 instead of a falsy check, per the review.",
  "files": [
    {
      "path": "src/cart.js",
      "content": "function calculateTotal(items) {
  return items.reduce((sum, item) => {
    const discountPercent = Math.min(item.discountPercent ?? 0, 100);
    const discount = discountPercent / 100;
    const lineTotal = item.price * item.qty * (1 - discount);
    return sum + lineTotal;
  }, 0);
}

module.exports = { calculateTotal };
